'use client'; import { useCallback, useEffect, useMemo, useState } from 'react'; import { VendorFeedbackBanner, useVendorFeedback } from '@/components/vendor/ui/useVendorFeedback';
import { VendorDataTable } from '@/components/vendor/ui/VendorDataTable';
import { VendorModuleHeader, VendorStatusPill } from '@/components/vendor/ui/VendorModuleHeader';
import { VendorAuditStrip } from '@/components/vendor/ui/VendorAuditStrip';
import { vendorFieldClass, vendorLabelClass, VendorModal } from '@/components/vendor/ui/VendorModal';
import { supabase } from '@/lib/supabaseClient';
import { MOCK_AUDIT_LOG, MOCK_QUOTE_REVISIONS, MOCK_RFQS } from '@/lib/vendor/mock/data';
import type { RFQRecord } from '@/lib/vendor/types/domain';
import { useActiveHospital } from '@/lib/vendor/store/vendor-app-store';
import { DEFAULT_VENDOR_ID } from '@/lib/vendor-supabase/constants';
import type { QuotationRow } from '@/lib/vendor-supabase/types'; export function QuotationsWorkspace() { const hospital = useActiveHospital(); const { feedback, showSuccess, showError } = useVendorFeedback(); const [selectedRfq, setSelectedRfq] = useState<string>(MOCK_RFQS[0]?.id ?? ''); const [quoteTotal, setQuoteTotal] = useState('4150000'); const [negotiationNote, setNegotiationNote] = useState(''); const [quotations, setQuotations] = useState<QuotationRow[]>([]); const [revisionOpen, setRevisionOpen] = useState(false); const [revisedAmount, setRevisedAmount] = useState(''); const [revisionNotes, setRevisionNotes] = useState(''); const [isSubmitting, setIsSubmitting] = useState(false); const rfqs = useMemo(() => { if (hospital.id === 'consolidated') return MOCK_RFQS; return MOCK_RFQS.filter((r) => r.hospitalId === hospital.id || r.status === 'Open'); }, [hospital.id]); const activeRfq = rfqs.find((r) => r.id === selectedRfq) ?? rfqs[0]; const activeQuotationId = useMemo(() => { const byRfq = quotations.find((q) => q.rfq_id === activeRfq?.id); return byRfq?.id ?? quotations[0]?.id ?? null; }, [quotations, activeRfq?.id]); const loadQuotations = useCallback(async () => { const { data, error } = await supabase .from('quotations') .select('*') .eq('vendor_id', DEFAULT_VENDOR_ID) .order('created_at', { ascending: false }); if (!error && data) setQuotations((data as QuotationRow[]) ?? []); }, []); useEffect(() => { void loadQuotations(); }, [loadQuotations]); const openRevisionModal = () => { if (!activeQuotationId) { window.alert('No quotation record in Supabase for this RFQ. Create a quotation row linked to rfq_id first.'); return; } setRevisedAmount(quoteTotal.replace(/,/g, '')); setRevisionNotes(negotiationNote); setRevisionOpen(true); }; const handleSubmitRevision = async (e: React.FormEvent) => { e.preventDefault(); if (!activeQuotationId) return; const amount = Number(revisedAmount); if (!Number.isFinite(amount) || amount <= 0) { window.alert('Enter a valid revised amount.'); return; } setIsSubmitting(true); const { error } = await supabase .from('quotations') .update({ total_amount: amount, notes: revisionNotes.trim() || null }) .eq('id', activeQuotationId); setIsSubmitting(false); if (error) { showError(error.message); window.alert(`Error: ${error.message}`); return; } showSuccess('Quote revision submitted successfully.'); setQuoteTotal(String(amount)); setRevisionOpen(false); await loadQuotations(); }; return ( <div className="space-y-6"> <VendorModuleHeader title="Quotations & Bids" description="Smart RFQ feed by specialty, response builder, revision history, tender portal, and procurement negotiation." actions={ <button type="button" onClick={openRevisionModal} className="rounded-xl bg-vendor-secondary px-4 py-2 text-xs font-bold text-white hover:opacity-90" > Submit quote revision </button> } /> <VendorFeedbackBanner feedback={feedback} /> <VendorDataTable<RFQRecord> rows={rfqs} rowKey={(r) => r.id} dense columns={[ { key: 'rfq', header: 'RFQ', render: (r) => ( <button type="button" onClick={() => setSelectedRfq(r.id)} className="text-left font-bold text-vendor-secondary "> {r.id} </button> ), }, { key: 'title', header: 'Title', render: (r) => r.title }, { key: 'match', header: 'Match', render: (r) => ( <VendorStatusPill label={r.matchTier} tone={r.matchTier === 'High Match' ? 'success' : r.matchTier === 'Medium Match' ? 'warning' : 'neutral'} /> ), }, { key: 'due', header: 'Due', render: (r) => r.dueDate }, { key: 'value', header: 'Est. value', render: (r) => r.estimatedValue }, ]} /> {activeRfq ? ( <div className="grid grid-cols-1 gap-6 xl:grid-cols-2"> <section className="rounded-2xl border border-vendor-accent/20 bg-vendor-card p-5 border-vendor-accent/20 bg-vendor-card"> <h2 className="text-sm font-black text-vendor-charcoal text-vendor-charcoal">RFQ response builder</h2> <p className="mt-1 text-xs text-vendor-muted text-vendor-muted">{activeRfq.title}</p> <label className="mt-4 block text-[10px] font-bold uppercase text-vendor-muted"> Total quote (INR) <input value={quoteTotal} onChange={(e) => setQuoteTotal(e.target.value)} className="mt-1 w-full rounded-lg border border-vendor-accent/20 px-3 py-2 font-mono text-sm " /> </label> <p className="mt-2 text-xs text-vendor-muted">Tier pricing pulled from catalog · HSN auto-mapped</p> </section> <section className="rounded-2xl border border-vendor-accent/20 bg-vendor-card p-5 border-vendor-accent/20 bg-vendor-card"> <h2 className="text-sm font-black text-vendor-charcoal text-vendor-charcoal">Quote revision history</h2> <ul className="mt-3 space-y-2"> {MOCK_QUOTE_REVISIONS.filter((q) => q.rfqId === activeRfq.id).map((rev) => ( <li key={rev.id} className="flex justify-between rounded-lg border border-slate-100 px-3 py-2 text-xs "> <span className="font-bold"> v{rev.version} · {rev.submittedAt} </span> <span className="font-mono">₹{rev.totalAmount.toLocaleString('en-IN')}</span> <VendorStatusPill label={rev.status} tone={rev.status === 'Under Negotiation' ? 'info' : 'neutral'} /> </li> ))} </ul> </section> <section className="rounded-2xl border border-vendor-accent/20 bg-vendor-card p-5 xl:col-span-2 border-vendor-accent/20 bg-vendor-card"> <h2 className="text-sm font-black text-vendor-charcoal text-vendor-charcoal">Negotiation panel · Hospital procurement</h2> <textarea value={negotiationNote} onChange={(e) => setNegotiationNote(e.target.value)} rows={3} placeholder="Counter-offer terms, delivery SLA, or payment milestone…" className="mt-3 w-full rounded-xl border border-vendor-accent/20 px-3 py-2 text-sm " /> <button type="button" className="mt-2 rounded-lg border border-vendor-accent/40 px-3 py-1.5 text-xs font-bold text-vendor-secondary "> Send secure message </button> </section> </div> ) : null} <VendorAuditStrip entries={MOCK_AUDIT_LOG.slice(0, 2)} /> <VendorModal title="Submit quote revision" open={revisionOpen} onClose={() => setRevisionOpen(false)} footer={ <> <button type="button" onClick={() => setRevisionOpen(false)} className="rounded-lg border px-4 py-2 text-sm font-bold"> Cancel </button> <button type="submit" form="quote-revision-form" disabled={isSubmitting} className="rounded-lg bg-vendor-secondary px-4 py-2 text-sm font-bold text-white disabled:opacity-60" > {isSubmitting ? 'Submitting…' : 'Submit revision'} </button> </> } > <form id="quote-revision-form" onSubmit={(e) => void handleSubmitRevision(e)} className="space-y-3"> <label className={vendorLabelClass}> Revised amount (INR) <input required type="number" min={1} value={revisedAmount} onChange={(e) => setRevisedAmount(e.target.value)} className={vendorFieldClass} /> </label> <label className={vendorLabelClass}> Revision notes <textarea rows={3} value={revisionNotes} onChange={(e) => setRevisionNotes(e.target.value)} className={vendorFieldClass} /> </label> </form> </VendorModal> </div> );
}
